import { expect, test } from "@playwright/test";
import { integrationHarness } from "./harness.ts";

const UC = "UC-ORDER-CANCEL-001";
// Printed right after the assert of a transition outcome passes (docs/trace.md)
const outcome = (node: string) => console.log(`[ESDD-OUTCOME] ${UC}__${node}`);

test(`${UC}__SC-001 an order progresses to delivered`, async ({ page }) => {
  const h = await integrationHarness(page);
  const orderId = await h.fixtures.paidOrder(); // PLACED

  // pack (staff): PLACED → PACKED
  let screen = await h.screen("staff", orderId);
  h.fake.respond("pack", { status: "PACKED" });
  await screen.expectStatusNot("status_packed");
  await screen.pack();
  await screen.expectStatus("status_packed");
  outcome("T-PLACED-pack-o1");
  expect(h.fake.calls("pack")).toHaveLength(1);

  // hand_over (staff): PACKED → HANDED_OVER
  h.fake.respond("hand_over", { status: "HANDED_OVER" });
  await screen.expectStatusNot("status_shipped");
  await screen.handOver();
  await screen.expectStatus("status_shipped");
  outcome("T-PACKED-hand_over-o1");
  expect(h.fake.calls("hand_over")).toHaveLength(1);

  // complete (system): HANDED_OVER → COMPLETED
  await screen.expectStatusNot("status_delivered");
  await h.fixtures.completeDelivery(orderId);
  await screen.refresh();
  await screen.expectStatus("status_delivered");
  outcome("T-HANDED_OVER-complete-o1");
});

