test(`${UC}__RACE-PLACED-pack-cancel-outcome pack loses to cancel`, async ({ page }) => {
  const h = await integrationHarness(page);
  const orderId = await h.fixtures.paidOrder(); // PLACED
  const screen = await h.screen("staff", orderId);

  // cancel wins: the order is CANCELED before pack (staff) commits
  h.fake.setStatus(orderId, "CANCELED");
  h.fake.rejectAsConflict("pack");
  await screen.expectNoCanceledNotice();
  await screen.pack();
  await screen.expectCanceledNotice();
});
